def change_access(session: Session, command: str, email: str, *, complex_id=None, role=None):
    email = validate_email(email.strip().casefold(), check_deliverability=False).normalized
    user = session.scalar(select(User).where(User.email == email))
    if user is None or not user.active:
        raise ValueError("An active, registered account is required.")
    if command == "set-client-role":
        if role not in {"player", "coach"}:
            raise ValueError("Invalid client role.")
        user.client_role = role
    else:
        complex_ = session.get(Complex, complex_id)
        if complex_ is None or not complex_.active:
            raise ValueError("An active complex is required.")
        assignment = session.scalar(
            select(StaffAssignment).where(
                StaffAssignment.user_id == user.id,
                StaffAssignment.complex_id == complex_id,
            )
        )
        if command == "revoke-staff":
            if assignment:
                assignment.active = False
        elif command == "grant-staff" and role in {"employee", "admin"}:
            if assignment is None:
                assignment = StaffAssignment(user_id=user.id, complex_id=complex_id, role=role)
                session.add(assignment)
            assignment.role = role
            assignment.active = True
        else:
            raise ValueError("Invalid staff command or role.")
    session.flush()

def verified_user(data: LoginInput, request: Request, session: Database):
    consume_attempts(session, request, str(data.email))
    user = session.scalar(select(User).where(User.email == str(data.email)))
    valid = password_matches(
        user.password_hash if user else dummy_hash, data.password.get_secret_value()
    )
    if user is None or not valid or not user.active:
        raise HTTPException(401, "Email or password is incorrect.")
    if passwords.check_needs_rehash(user.password_hash):
        user.password_hash = passwords.hash(data.password.get_secret_value())
    return user

def login(data: LoginInput, request: Request, response: Response, session: Database):
    user = verified_user(data, request, session)
    csrf = create_session(session, request, response, user)
    return account(session, user, csrf)

def staff_login(data: LoginInput, request: Request, response: Response, session: Database):
    user = verified_user(data, request, session)
    if not account(session, user, "").staff_assignments:
        raise HTTPException(
            403, "Staff access has not been assigned to this account. Contact your administrator."
        )
    csrf = create_session(session, request, response, user)
    return account(session, user, csrf)

def staff_me(identity: CurrentIdentity, session: Database):
    data = account(session, identity.user, csrf_token(identity.token))
    if not data.staff_assignments:
        raise HTTPException(403, "Staff access has not been assigned to this account.")
    return data

def session_status(request: Request, session: Database):
    try:
        identity = current_identity(request, session)
    except HTTPException as error:
        if error.status_code == 401:
            return None
        raise
    return account(session, identity.user, csrf_token(identity.token))

def complex_assignment(
    complex_id: UUID, identity: CurrentIdentity, session: Database
) -> StaffAssignment:
    assignment = session.scalar(
        select(StaffAssignment)
        .join(Complex)
        .where(
            StaffAssignment.complex_id == complex_id,
            StaffAssignment.user_id == identity.user.id,
            StaffAssignment.active.is_(True),
            Complex.active.is_(True),
        )
    )
    if assignment is None:
        raise HTTPException(403, "You do not have staff access to this complex.")
    return assignment

