def main():
    result = subprocess.run(["git", "ls-files", "-z"], check=True, capture_output=True)
    forbidden = []
    for name in result.stdout.decode().split("\0"):
        if not name:
            continue
        path = PurePosixPath(name)
        if path.suffix.lower() in {".md", ".markdown", ".pdf"}:
            forbidden.append(name)
        if path.name.startswith(".env") and path.name not in {
            ".env.example",
            ".env.sample",
            ".env.template",
        }:
            forbidden.append(name)
    if forbidden:
        raise SystemExit("Private files must not be tracked: " + ", ".join(forbidden))
    print("Repository privacy check passed.")

def docker_command() -> str:
    command = shutil.which("docker")
    if command:
        return command
    if os.name == "nt":
        candidate = (
            Path(os.environ.get("LOCALAPPDATA", ""))
            / "Programs/DockerDesktop/resources/bin/docker.exe"
        )
        if candidate.is_file():
            return str(candidate)
    raise SystemExit("Docker was not found. Install/start Docker, then run this command again.")

def main():
    parser = argparse.ArgumentParser(
        description="Run the OmniSport application and its isolated database tests."
    )
    commands = parser.add_subparsers(dest="command", required=True)
    start = commands.add_parser(
        "start", help="Build/start the app and database; preserve existing data."
    )
    start.add_argument(
        "--demo", action="store_true", help="Also add the two fictional demonstration complexes."
    )
    commands.add_parser("test", help="Run tests against SQLite and a disposable MySQL database.")
    access = commands.add_parser(
        "access", help="Run the trusted role-assignment CLI in the app container."
    )
    access.add_argument("arguments", nargs=argparse.REMAINDER)
    commands.add_parser(
        "stop", help="Stop this project's services without deleting its database volume."
    )
    args = parser.parse_args()
    docker = docker_command()

    def run(*parts):
        subprocess.run([docker, "compose", *parts], cwd=ROOT, check=True)

    try:
        if args.command == "stop":
            if not (ROOT / ".env").exists():
                print("No local setup found; nothing to stop.")
                return
            run("--profile", "test", "stop", "app", "db", "migrate", "test-db")
            return
        configure()
        if args.command == "access":
            run("exec", "-T", "app", "python", "-m", "backend.app.accounts", *args.arguments)
            return
        if args.command == "start":
            run("up", "-d", "--build", "--wait", "--wait-timeout", "180", "app")
            if args.demo:
                run("--profile", "tools", "run", "--rm", "seed")
            print("Application ready at http://127.0.0.1:8000 (unless OMNI_HTTP_PORT was changed).")
        else:
            try:
                run(
                    "--profile",
                    "test",
                    "up",
                    "--build",
                    "--abort-on-container-exit",
                    "--exit-code-from",
                    "test",
                    "test",
                )
            finally:
                run("--profile", "test", "stop", "test-db")
    except subprocess.CalledProcessError as failure:
        raise SystemExit(failure.returncode) from None

def database(request, tmp_path):
    if request.param == "mysql":
        url = os.environ.get("OMNI_TEST_DATABASE_URL")
        if not url:
            if os.environ.get("CI") == "true":
                pytest.fail("CI requires OMNI_TEST_DATABASE_URL; MySQL tests must not be skipped")
            pytest.skip(
                "Set OMNI_TEST_DATABASE_URL or run the Docker test service for MySQL checks"
            )
        parsed = make_url(url)
        if parsed.get_backend_name() != "mysql" or not (parsed.database or "").endswith("_test"):
            raise RuntimeError(
                "MySQL tests require an isolated database whose name ends with _test"
            )
    else:
        url = f"sqlite+pysqlite:///{(tmp_path / 'catalogue_test.sqlite').as_posix()}"
    settings = Settings(database_url=url, auth_origins=["http://testserver"], _env_file=None)
    engine = make_engine(settings)
    config = Config(str(ROOT / "alembic.ini"))
    with engine.begin() as connection:
        config.attributes["connection"] = connection
        command.upgrade(config, "head")
    with engine.connect() as connection:
        transaction = connection.begin()
        session = Session(bind=connection, join_transaction_mode="create_savepoint")
        try:
            yield settings, engine, session
        finally:
            session.close()
            if transaction.is_active:
                transaction.rollback()
    engine.dispose()

